import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

cuda_decl = r"""
#include <torch/extension.h>
torch::Tensor cute_tanh_forward(torch::Tensor x);
"""

cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <cute/tensor.hpp>

using namespace cute;

__global__ void tanh_kernel_vec4(
    const float* __restrict__ X,
    float* __restrict__ Y,
    int64_t N4,
    int64_t Ntail_start,
    int64_t N)
{
    int64_t tid    = (int64_t)blockIdx.x * blockDim.x + threadIdx.x;
    int64_t stride = (int64_t)gridDim.x * blockDim.x;
    // Vectorized part: process float4 chunks via direct pointer access
    // (avoids extra abstraction overhead / register pressure from CUTE tensor indexing)
    const float4* __restrict__ X4 = reinterpret_cast<const float4*>(X);
    float4* __restrict__ Y4 = reinterpret_cast<float4*>(Y);
    #pragma unroll 4
    for (int64_t i = tid; i < N4; i += stride) {
        float4 v = X4[i];
        float4 r;
        r.x = tanhf(v.x);
        r.y = tanhf(v.y);
        r.z = tanhf(v.z);
        r.w = tanhf(v.w);
        Y4[i] = r;
    }
    // Tail scalar part (elements not covered by float4 vectorization)
    int64_t tail_count = N - Ntail_start;
    if (tail_count > 0) {
        for (int64_t i = tid; i < tail_count; i += stride) {
            Y[Ntail_start + i] = tanhf(X[Ntail_start + i]);
        }
    }
}

torch::Tensor cute_tanh_forward(torch::Tensor x) {
    TORCH_CHECK(x.is_cuda(), "x must be a CUDA tensor");
    TORCH_CHECK(x.scalar_type() == at::kFloat, "x must be float32");

    auto x_c = x.contiguous();
    auto y = torch::empty_like(x_c);

    int64_t N = x_c.numel();
    int64_t N4 = N / 4;
    int64_t Ntail_start = N4 * 4;

    const int threads = 512;
    int64_t blocks64 = (N4 > 0 ? (N4 + threads - 1) / threads : 1);
    if (blocks64 < 1) blocks64 = 1;
    if (blocks64 > 65535) blocks64 = 65535; // grid-stride loop handles the rest
    dim3 grid((unsigned)blocks64);
    dim3 block(threads);

    cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();

    tanh_kernel_vec4<<<grid, block, 0, stream>>>(
        x_c.data_ptr<float>(),
        y.data_ptr<float>(),
        N4,
        Ntail_start,
        N
    );

    auto err = cudaGetLastError();
    TORCH_CHECK(err == cudaSuccess, "tanh_kernel_vec4 launch failed: ", cudaGetErrorString(err));

    return y.view(x.sizes());
}
"""

cute_tanh_ext = load_inline(
    name="cute_tanh_ext",
    cpp_sources=cuda_decl,
    cuda_sources=cuda_src,
    functions=["cute_tanh_forward"],
    extra_cflags=["-O3"],
    extra_cuda_cflags=["-O3", "--use_fast_math"],
    extra_include_paths=["/root/cutegen_test/cutegen/cutlass/include"],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    Simple model that performs a Tanh activation using a custom CUTE/CUDA kernel.
    """
    def __init__(self):
        super(ModelNew, self).__init__()
        self._ext = cute_tanh_ext

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return self._ext.cute_tanh_forward(x)

